const CHAT_ID = process.env.TELEGRAM_CHAT_ID;

if (!BOT_TOKEN) {
  console.error('❌ Error: TELEGRAM_BOT_TOKEN not found in environment');
  console.error('Available env vars:', Object.keys(process.env).filter(k => k.includes('TELEGRAM')));
  process.exit(1);
}

if (!CHAT_ID) {
  console.error('❌ Error: TELEGRAM_CHAT_ID not found in environment');
  console.error('Please set TELEGRAM_CHAT_ID with your chat ID');
  process.exit(1);
}

// Read the briefing markdown
const briefingPath = path.join(__dirname, 'sterling_briefing.md');
const briefing = fs.readFileSync(briefingPath, 'utf8');

// Convert markdown to HTML for Telegram
function mdToTelegramHtml(md) {
  let html = md;

  // Headers
  html = html.replace(/^# (.+)$/gm, '<b>$1</b>');
  html = html.replace(/^## (.+)$/gm, '\n<b>$1</b>');
  html = html.replace(/^### (.+)$/gm, '\n<b>$1</b>');

  // Bold
  html = html.replace(/\*\*(.+?)\*\*/g, '<b>$1</b>');

  // Italic
  html = html.replace(/\*(.+?)\*/g, '<i>$1</i>');

  // Code blocks
  html = html.replace(/```[\s\S]+?```/g, '');

  // Inline code
  html = html.replace(/`(.+?)`/g, '<code>$1</code>');

  // Remove markdown separators
  html = html.replace(/^---$/gm, '');

  // Lists (simplified)
  html = html.replace(/^- /gm, '• ');
  html = html.replace(/^\d+\. /gm, '');

  // Clean up multiple newlines
  html = html.replace(/\n{3,}/g, '\n\n');

  return html.trim();
}

async function postBriefing() {
  try {
    const htmlContent = mdToTelegramHtml(briefing);

    console.log('📤 Posting Sterling Intelligence Briefing to Telegram...');
    console.log(`Bot Token: ${BOT_TOKEN.substring(0, 10)}...`);
    console.log(`Chat ID: ${CHAT_ID}`);

    const result = await sendMessage(BOT_TOKEN, CHAT_ID, htmlContent, {
      disablePreview: false
    });

    console.log('✅ Briefing posted successfully!');
    console.log('Message ID:', result.message_id);
  } catch (error) {
    console.error('❌ Error posting to Telegram:', error.message);
    if (error.response) {
      console.error('Response:', error.response.data);
    }
    process.exit(1);
  }
}

postBriefing();

