#!/usr/bin/env node

/**
 * Post Sterling Intelligence Briefing to Telegram
 * 
 * This script reads the briefing markdown and posts it to Telegram.
 * Requires TELEGRAM_BOT_TOKEN and TELEGRAM_CHAT_ID in environment or LLM_SECRETS.
 * 
 * Usage:
 *   node post_briefing.js [briefing_file] [bot_token] [chat_id]
 * 
 * Arguments are optional if environment variables are set.
 */

const fs = require('fs');
const path = require('path');
const { sendMessage } = require(path.join(__dirname, '../event_handler/tools/telegram.js'));

// Get credentials from arguments or environment
const briefingFile = process.argv[2] || path.join(__dirname, 'sterling_briefing.md');
const BOT_TOKEN = process.argv[3] || process.env.TELEGRAM_BOT_TOKEN;
const CHAT_ID = process.argv[4] || process.env.TELEGRAM_CHAT_ID;

// Convert markdown to Telegram HTML
function mdToTelegramHtml(md) {
  let html = md;

  // Headers (must come before bold to avoid double-processing **)
  html = html.replace(/^# (.+)$/gm, '<b>$1</b>');
  html = html.replace(/^## (.+)$/gm, '\n<b>$1</b>');
  html = html.replace(/^### (.+)$/gm, '\n<b>$1</b>');

  // Bold (avoid processing already converted headers)
  html = html.replace(/\*\*([^*]+?)\*\*/g, '<b>$1</b>');

  // Italic
  html = html.replace(/\*([^*]+?)\*/g, '<i>$1</i>');

  // Code blocks (remove them - Telegram doesn't render well)
  html = html.replace(/```[\s\S]+?```/g, '');

  // Inline code
  html = html.replace(/`([^`]+?)`/g, '<code>$1</code>');

  // Horizontal rules
  html = html.replace(/^---$/gm, '━━━━━━━━━━━━━━━');

  // Lists
  html = html.replace(/^- /gm, '• ');
  html = html.replace(/^\d+\. /gm, '');

  // Clean up multiple newlines
  html = html.replace(/\n{3,}/g, '\n\n');

  return html.trim();
}

async function main() {
  try {
    // Check if briefing file exists
    if (!fs.existsSync(briefingFile)) {
      console.error(`❌ Error: Briefing file not found: ${briefingFile}`);
      process.exit(1);
    }

    // Check credentials
    if (!BOT_TOKEN) {
      console.error('❌ Error: TELEGRAM_BOT_TOKEN not provided');
      console.error('');
      console.error('Please provide bot token via:');
      console.error('  1. Environment variable: export TELEGRAM_BOT_TOKEN="..."');
      console.error('  2. Command argument: node post_briefing.js [file] [token] [chat_id]');
      console.error('  3. Add to LLM_SECRETS in GitHub secrets');
      console.error('');
      process.exit(1);
    }

    if (!CHAT_ID) {
      console.error('❌ Error: TELEGRAM_CHAT_ID not provided');
      console.error('');
      console.error('Please provide chat ID via:');
      console.error('  1. Environment variable: export TELEGRAM_CHAT_ID="..."');
      console.error('  2. Command argument: node post_briefing.js [file] [token] [chat_id]');
      console.error('  3. Add to LLM_SECRETS in GitHub secrets');
      console.error('');
      console.error('To get your chat ID:');
      console.error('  - Message your bot');
      console.error('  - Use @userinfobot on Telegram');
      console.error('  - Check event handler logs for webhook payloads');
      console.error('');
      process.exit(1);
    }

    // Read and convert briefing
    console.log(`📖 Reading briefing from: ${briefingFile}`);
    const briefing = fs.readFileSync(briefingFile, 'utf8');
    const htmlContent = mdToTelegramHtml(briefing);

    // Post to Telegram
    console.log('📤 Posting to Telegram...');
    console.log(`   Bot Token: ${BOT_TOKEN.substring(0, 10)}...`);
    console.log(`   Chat ID: ${CHAT_ID}`);
    console.log(`   Content length: ${htmlContent.length} characters`);

    const result = await sendMessage(BOT_TOKEN, CHAT_ID, htmlContent, {
      disablePreview: false
    });

    console.log('');
    console.log('✅ Sterling Intelligence Briefing posted successfully!');
    console.log(`   Message ID: ${result.message_id}`);
    console.log(`   Chat: ${result.chat.type} (${result.chat.id})`);
    if (result.chat.title) {
      console.log(`   Title: ${result.chat.title}`);
    }

  } catch (error) {
    console.error('');
    console.error('❌ Error posting to Telegram:', error.message);
    if (error.response?.data) {
      console.error('API Response:', JSON.stringify(error.response.data, null, 2));
    }
    console.error('');
    process.exit(1);
  }
}

main();

#!/usr/bin/env node

/**
 * Simple Telegram poster using only built-in Node.js fetch
 * No external dependencies required
 */

const fs = require('fs');
const path = require('path');

const briefingFile = process.argv[2] || path.join(__dirname, 'sterling_briefing.md');
const BOT_TOKEN = process.argv[3] || process.env.TELEGRAM_BOT_TOKEN;
const CHAT_ID = process.argv[4] || process.env.TELEGRAM_CHAT_ID;

const MAX_MESSAGE_LENGTH = 4096;

// Convert markdown to Telegram HTML
function mdToTelegramHtml(md) {
  let html = md;

  // Headers
  html = html.replace(/^# (.+)$/gm, '<b>$1</b>');
  html = html.replace(/^## (.+)$/gm, '\n<b>$1</b>');
  html = html.replace(/^### (.+)$/gm, '\n<b>$1</b>');

  // Bold
  html = html.replace(/\*\*([^*]+?)\*\*/g, '<b>$1</b>');

  // Italic
  html = html.replace(/\*([^*]+?)\*/g, '<i>$1</i>');

  // Code blocks
  html = html.replace(/```[\s\S]+?```/g, '');

  // Inline code
  html = html.replace(/`([^`]+?)`/g, '<code>$1</code>');

  // Horizontal rules
  html = html.replace(/^---$/gm, '━━━━━━━━━━━━━━━');

  // Lists
  html = html.replace(/^- /gm, '• ');
  html = html.replace(/^\d+\. /gm, '');

  // Clean up
  html = html.replace(/\n{3,}/g, '\n\n');

  return html.trim();
}

// Split message into chunks if needed
function splitMessage(text, maxLength = MAX_MESSAGE_LENGTH) {
  if (text.length <= maxLength) return [text];

  const chunks = [];
  let remaining = text;

  while (remaining.length > 0) {
    if (remaining.length <= maxLength) {
      chunks.push(remaining);
      break;
    }

    const chunk = remaining.slice(0, maxLength);
    let splitAt = -1;

    // Try to split at natural boundaries
    for (const delim of ['\n\n', '\n', '. ', ' ']) {
      const idx = chunk.lastIndexOf(delim);
      if (idx > maxLength * 0.3) {
        splitAt = idx + delim.length;
        break;
      }
    }

    if (splitAt === -1) splitAt = maxLength;

    chunks.push(remaining.slice(0, splitAt).trimEnd());
    remaining = remaining.slice(splitAt).trimStart();
  }

  return chunks;
}

// Send message to Telegram
async function sendToTelegram(botToken, chatId, text) {
  const url = `https://api.telegram.org/bot${botToken}/sendMessage`;

  const response = await fetch(url, {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify({
      chat_id: chatId,
      text: text,
      parse_mode: 'HTML',
      disable_web_page_preview: false
    })
  });

  const data = await response.json();

  if (!data.ok) {
    throw new Error(`Telegram API error: ${data.description || 'Unknown error'}`);
  }

  return data.result;
}

async function main() {
  try {
    // Validate inputs
    if (!fs.existsSync(briefingFile)) {
      console.error(`❌ Error: Briefing file not found: ${briefingFile}`);
      process.exit(1);
    }

    if (!BOT_TOKEN) {
      console.error('❌ Error: TELEGRAM_BOT_TOKEN not provided');
      console.error('');
      console.error('Set up Telegram credentials:');
      console.error('  1. Get bot token from @BotFather');
      console.error('  2. Add to LLM_SECRETS in GitHub repository secrets:');
      console.error('     {"TELEGRAM_BOT_TOKEN":"...","TELEGRAM_CHAT_ID":"..."}');
      console.error('  3. Encode as base64 and set as LLM_SECRETS secret');
      console.error('');
      process.exit(1);
    }

    if (!CHAT_ID) {
      console.error('❌ Error: TELEGRAM_CHAT_ID not provided');
      console.error('');
      console.error('To get your chat ID:');
      console.error('  - Message your bot on Telegram');
      console.error('  - Use @userinfobot to get your user ID');
      console.error('  - For groups/channels, add bot and check logs');
      console.error('');
      process.exit(1);
    }

    // Read and convert
    console.log(`📖 Reading: ${briefingFile}`);
    const markdown = fs.readFileSync(briefingFile, 'utf8');
    const html = mdToTelegramHtml(markdown);
    const chunks = splitMessage(html);

    console.log(`📤 Posting ${chunks.length} message(s) to Telegram...`);
    console.log(`   Bot: ${BOT_TOKEN.substring(0, 10)}...`);
    console.log(`   Chat: ${CHAT_ID}`);

    // Send all chunks
    let lastResult;
    for (let i = 0; i < chunks.length; i++) {
      console.log(`   Sending part ${i + 1}/${chunks.length} (${chunks[i].length} chars)...`);
      lastResult = await sendToTelegram(BOT_TOKEN, CHAT_ID, chunks[i]);

      // Small delay between messages
      if (i < chunks.length - 1) {
        await new Promise(resolve => setTimeout(resolve, 500));
      }
    }

    console.log('');
    console.log('✅ Sterling Intelligence Briefing posted successfully!');
    console.log(`   Message ID: ${lastResult.message_id}`);
    console.log(`   Date: ${new Date(lastResult.date * 1000).toISOString()}`);

  } catch (error) {
    console.error('');
    console.error('❌ Error:', error.message);
    if (error.stack) {
      console.error(error.stack);
    }
    console.error('');
    process.exit(1);
  }
}

main();
